"""Visual-servoed peg insertion qualification on ALOHA-2 #4."""
import re
import workcell

def cmd(tool,*args):
    r=workcell.call(tool,*args)
    print(tool,*args,':',r.text,flush=True)
    if not r.ok: raise RuntimeError(r.text)
    return r

def see():
    text=cmd('vision','locate').text
    hole=re.search(r'socket hole centre: x=([\d.-]+) y=([\d.-]+) mm, top at z=([\d.-]+)',text)
    tip=re.search(r'lower end x=([\d.-]+) y=([\d.-]+) z=([\d.-]+) mm; tilt ([\d.-]+)',text)
    if not (hole and tip): raise RuntimeError('hole or peg not visible')
    return tuple(map(float,hole.groups())),tuple(map(float,tip.groups()))

def align(max_delta=4.0):
    hole,tip=see()
    ex,ey=hole[0]-tip[0],hole[1]-tip[1]
    if abs(ex)>max_delta or abs(ey)>max_delta: raise RuntimeError('alignment discrepancy too large')
    if abs(ex)>0.6 or abs(ey)>0.6:
        # step compensates camera-measured tip-to-hole offset without relying on arm calibration.
        cmd('robot','step','right',f'{ex:.2f}',f'{ey:.2f}','0')
        hole,tip=see()
    return hole,tip

def run():
    cmd('trial','start')
    cmd('robot','pick','cap','--arm','left')
    cmd('robot','place','bin','--arm','left')
    cmd('robot','pick','peg','--arm','right')
    cmd('robot','move','right','0','60','155')
    align()
    cmd('robot','step','right','0','0','-20')
    cmd('robot','step','right','0','0','-17')
    hole,tip=align()
    if abs(tip[2]-hole[2])>7: raise RuntimeError('peg not at socket mouth')
    for dz in (-10,-15,-11):
        cmd('robot','step','right','0','0',str(dz))
        hole,tip=see()
        if abs(tip[0]-hole[0])>3 or abs(tip[1]-hole[1])>3 or tip[3]>4:
            raise RuntimeError('peg lost alignment during insertion')
    # The 40-mm-deep socket bottoms at top - 40. Vision measures the physical lower end.
    depth=hole[2]-tip[2]
    if depth<39:
        extra=min(5,39.5-depth)
        cmd('robot','step','right','0','0',f'{-extra:.2f}')
        hole,tip=see()
        depth=hole[2]-tip[2]
    if depth<39: raise RuntimeError('insertion not fully seated: depth '+str(depth))
    cmd('robot','grip','right','open')
    cmd('robot','move','right','0','60','160')
    hole,tip=see()
    if hole[2]-tip[2]<39: raise RuntimeError('peg lifted when gripper retracted')
    result=cmd('trial','end')
    if 'SUCCESS' not in result.text: raise RuntimeError('qualification trial failed')

if __name__=='__main__':
    for _ in range(2): run()
