import re, workcell

def cmd(tool,*args):
 r=workcell.call(tool,*args); print(tool,*args,':',r.text,flush=True)
 if not r.ok: raise RuntimeError(r.text)
 return r

def see():
 t=cmd('vision','locate').text
 h=re.search(r'socket hole centre: x=([\d.-]+) y=([\d.-]+) mm, top at z=([\d.-]+)',t)
 p=re.search(r'lower end x=([\d.-]+) y=([\d.-]+) z=([\d.-]+) mm; tilt ([\d.-]+)',t)
 if not h or not p: raise RuntimeError('vision lost')
 return list(map(float,h.groups())),list(map(float,p.groups()))

def align(h,p):
 x,y=h[0]-p[0],h[1]-p[1]
 if max(abs(x),abs(y))>12 or p[3]>4: raise RuntimeError('unreliable peg grasp / alignment')
 if max(abs(x),abs(y))>0.7:
  cmd('robot','step','right',f'{x:.2f}',f'{y:.2f}','0')
  h,p=see()
 return h,p

def insert():
 cmd('robot','move','right','0','60','155')
 h,p=align(*see())
 while p[2]>h[2]+3:
  dz=min(19,max(1,p[2]-h[2]-1))
  cmd('robot','step','right','0','0',f'{-dz:.2f}')
  h,p=see()
  if p[3]>5: raise RuntimeError('peg tilted while approaching socket')
  if p[2]<h[2]+12: h,p=align(h,p)
 h,p=align(h,p)
 if not h[2]-4<=p[2]<=h[2]+4: raise RuntimeError('socket mouth approach incorrect')
 while h[2]-p[2]<39.5:
  dz=min(12,39.5-(h[2]-p[2]))
  cmd('robot','step','right','0','0',f'{-dz:.2f}')
  h,p=see()
  if p[3]>5 or abs(p[0]-h[0])>3.5 or abs(p[1]-h[1])>3.5: raise RuntimeError('peg misaligned in socket')
 cmd('robot','grip','right','open')
 cmd('robot','move','right','0','60','160')
 h,p=see()
 if h[2]-p[2]<39: raise RuntimeError('peg not seated after release')
 r=cmd('trial','end')
 if 'SUCCESS' not in r.text: raise RuntimeError('trial not successful')

if __name__=='__main__': insert()
